SELECT 



        (e.emp_no LIKE CONCAT('%', #{q.keyword}, '%') OR e.name LIKE CONCAT('%', #{q.keyword}, '%')
         OR e.phone LIKE CONCAT('%', #{q.keyword}, '%'))


        AND e.dept_id IN #{d}

    AND e.status = #{q.status}
    AND e.status <> 'LEFT'
    AND e.position_id = #{q.positionId}
    AND e.emp_type = #{q.empType}

ORDER BY e.emp_no

SELECT e.id, e.emp_no, e.name, e.dept_id, d.name AS dept_name, e.user_id FROM hr_employee e LEFT JOIN sys_dept d ON d.id = e.dept_id WHERE e.status <> 'LEFT'
AND (e.emp_no LIKE CONCAT('%', #{keyword}, '%') OR e.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY e.emp_no LIMIT #{limit}
